# Verify dictionary
LANGS = ["en", "es", "hi", "ta", "te", "kn", "ml", "bn", "mr", "gu", "pa", "or"]
for lang in LANGS:
    assert lang in I18N, f"Missing language: {lang}"
    for k in KEYS:
        assert k in I18N[lang], f"Missing key {k} in {lang}"
        assert len(I18N[lang][k]) > 0, f"Empty key {k} in {lang}"

print(f"Verified all 12 languages and all {len(KEYS)} keys successfully!")

with open("scratch/ui_strings_full.json", "w", encoding="utf-8") as f:
    json.dump(I18N, f, ensure_ascii=False, indent=2)

print("Saved scratch/ui_strings_full.json")
